import {api,send,subscriptionLabel} from './platform.mjs';
import {escapeHtml as esc,parseMoney} from './core.mjs';
import {adminSession,showAdminLogin,showAdminDenied} from './admin-access.mjs';
const root=document.querySelector('#admin-content'),status=document.querySelector('#admin-status');
let catalog={plans:[],revision:0},page=1,query='',busy=false;
const notice=message=>{status.textContent=message;status.focus({preventScroll:true});};
const date=value=>value?new Date(value).toLocaleDateString('pt-BR'):'Sem prazo definido';
const navigation=document.querySelector('.admin-sections'),identity=document.querySelector('#admin-session');
function hideAdministration(){navigation.hidden=true;identity.hidden=true;identity.replaceChildren();status.textContent='';}
function accessError(error){
 if(error.status===401){hideAdministration();showAdminLogin(root,start,'Sua sessão terminou. Entre novamente para continuar.');return;}
 if(error.status===403){void start();return;}
 notice(error.message);
}
async function overview(){const data=await api('admin/overview');document.querySelector('#admin-overview').innerHTML=`<div class="admin-metrics">${[[data.counts.users,'contas cadastradas'],[data.counts.active,'assinaturas ativas'],[data.counts.monthlyRequests,'mensagens neste mês']].map(([n,t])=>`<article class="card"><strong>${Number(n).toLocaleString('pt-BR')}</strong><span>${t}</span></article>`).join('')}</div><section class="card admin-connections"><h2>Conexões da operação</h2><ul><li>Banco de dados <b>Conectado</b></li><li>DeepSeek <b>${data.integrations.deepseek?'Chave configurada':'Aguardando chave'}</b></li><li>WhatsApp <b>${data.integrations.whatsapp?'Configurado':'Aguardando Meta'}</b></li><li>Áudio <b>${data.integrations.audio?'Workers AI vinculado':'Aguardando Workers AI'}</b></li><li>Push <b>${data.integrations.push?'Chaves configuradas':'Aguardando configuração'}</b></li><li>Pagamentos <b>Aguardando gateway</b></li></ul><p>Uso contabilizado em ${esc(data.month)} (UTC). Uma chave configurada ainda precisa ser validada com o provedor.</p></section>`;}
function renderPlans(){document.querySelector('#admin-plans').innerHTML=`<section aria-labelledby="catalog-title"><p class="eyebrow">OFERTA COMERCIAL</p><h2 id="catalog-title">Três planos, do seu jeito.</h2><p>Os valores ficam visíveis no site após salvar. A cobrança permanece indisponível até configurar o gateway. Alterar o limite de IA vale imediatamente para todos os assinantes daquele plano.</p><form id="catalog-form"><div class="portal-plans">${catalog.plans.map(p=>`<fieldset class="card"><legend>${esc(p.name)}</legend><p class="small muted">Identificador: ${p.id}</p><label>Nome<input name="${p.id}.name" value="${esc(p.name)}" maxlength="60" required></label><label>Descrição<textarea name="${p.id}.description" maxlength="240" rows="3" required>${esc(p.description)}</textarea></label><label>Preço mensal em R$<input name="${p.id}.price" value="${p.priceCents===null?'':(p.priceCents/100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2,useGrouping:false})}" inputmode="decimal" placeholder="Deixe vazio para definir depois"></label><label>Mensagens de IA por mês<input name="${p.id}.monthlyRequests" type="number" min="1" max="1000000" value="${p.monthlyRequests}" required></label></fieldset>`).join('')}</div><button class="primary" type="submit">Salvar os três planos</button></form></section>`;}
async function users(){const result=await api('admin/users?'+new URLSearchParams({page:String(page),q:query}));document.querySelector('#admin-users').innerHTML=`<p>${result.total.toLocaleString('pt-BR')} ${result.total===1?'conta encontrada':'contas encontradas'} · Página ${result.page} de ${Math.max(1,Math.ceil(result.total/result.pageSize))}</p><div class="admin-user-list">${result.users.map(u=>`<article class="card"><div class="admin-user-head"><div><h3>${esc(u.name)}</h3><p>${esc(u.email)}</p></div><span class="badge">${esc(subscriptionLabel(u.status==='active'&&u.current_period_end&&u.current_period_end<Date.now()?'expired':u.status))}</span></div><p class="small muted">Cadastro: ${date(u.created_at)} · Acesso até: ${date(u.current_period_end)}</p><form data-user="${u.id}" class="admin-user-form"><label>Plano<select name="plan">${catalog.plans.map(p=>`<option value="${p.id}" ${p.id===u.plan?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Status<select name="status">${['pending','active','canceled'].map(s=>`<option value="${s}" ${s===u.status?'selected':''}>${subscriptionLabel(s)}</option>`).join('')}</select></label><label>Vigência a partir de hoje (dias)<input name="days" type="number" min="1" max="366" value="30" required></label><button class="outline" type="submit">Salvar acesso</button></form></article>`).join('')||'<p>Nenhuma conta corresponde à busca.</p>'}</div><nav class="admin-pagination" aria-label="Páginas de usuários"><button type="button" class="outline" data-admin-page="${page-1}" ${page<=1?'disabled':''}>← Anterior</button><button type="button" class="outline" data-admin-page="${page+1}" ${page*result.pageSize>=result.total?'disabled':''}>Próxima →</button></nav>`;}
async function start(){hideAdministration();try{const user=await adminSession();if(user.role!=='admin'){showAdminDenied(root,user,start);return;}catalog=await api('admin/plans');identity.innerHTML=`<span>ADMIN MASTER · ${esc(user.email)}</span><button type="button" class="outline" id="admin-logout">Sair do painel</button>`;identity.hidden=false;navigation.hidden=false;identity.querySelector('button').onclick=async event=>{event.target.disabled=true;try{await send('logout',{});hideAdministration();showAdminLogin(root,start);}catch(error){accessError(error);if(event.target.isConnected)event.target.disabled=false;}};root.innerHTML='<section id="admin-overview"></section><div id="admin-plans"></div><section aria-labelledby="users-title" class="admin-users-section"><p class="eyebrow">CONTAS E ACESSOS</p><h2 id="users-title">Quem está com a Mentra.</h2><p>Liberações manuais servem para homologação ou acesso concedido pela administração. Elas não confirmam recebimento de pagamento.</p><form id="admin-search" class="admin-search"><label>Buscar por nome ou e-mail<input name="query" maxlength="200" type="search"></label><button class="outline" type="submit">Buscar contas</button></form><div id="admin-users"></div></section>';renderPlans();await Promise.all([overview(),users()]);}catch(error){hideAdministration();if(error.status===401){showAdminLogin(root,start);return;}root.innerHTML='<section class="card"><h2>Não foi possível abrir o painel.</h2><p role="alert"></p><button class="primary" type="button">Tentar novamente</button></section>';root.querySelector('p').textContent=error.message;root.querySelector('button').onclick=start;}}
root.addEventListener('submit',async e=>{
 if(!['admin-search','catalog-form'].includes(e.target.id)&&!e.target.dataset.user)return;
 e.preventDefault();if(busy)return;const form=e.target,raw=Object.fromEntries(new FormData(form)),button=form.querySelector('button[type="submit"]');busy=true;if(button)button.disabled=true;
 try{
  if(form.id==='admin-search'){query=raw.query.trim();page=1;await users();return;}
  if(form.id==='catalog-form'){
   const plans=catalog.plans.map(p=>{const price=raw[p.id+'.price'].trim(),priceCents=price?parseMoney(price):null;if(price&&priceCents===null)throw Error('Informe o preço no formato 29,90.');return {id:p.id,name:raw[p.id+'.name'],description:raw[p.id+'.description'],priceCents,monthlyRequests:Number(raw[p.id+'.monthlyRequests'])};});
   catalog=await send('admin/plans',{plans,revision:catalog.revision},'PUT');renderPlans();await users();notice('Planos atualizados no site e no controle de uso da IA.');return;
  }
  if(form.dataset.user){await send('admin/subscription',{userId:form.dataset.user,plan:raw.plan,status:raw.status,days:Number(raw.days)});await Promise.all([users(),overview()]);notice('Acesso atualizado. A alteração foi registrada na auditoria.');}
 }catch(error){accessError(error);}finally{busy=false;if(button?.isConnected)button.disabled=false;}
});
root.addEventListener('click',async e=>{const button=e.target.closest('[data-admin-page]');if(!button||busy)return;busy=true;const prior=page;page=Number(button.dataset.adminPage);try{await users();}catch(error){page=prior;accessError(error);}finally{busy=false;}});
start();
